-- Live Wire - Viewpoint models: registers the model manifests of the Live Wire tiles
-- with Project Viewpoint's model pack API (arguments: mod id, manifest path relative
-- to this mod; each mod id + path pair is a separate pack). Does nothing when Viewpoint
-- is not active. The LiveWire Extended manifest is registered only when that sub-mod
-- is active. The models and the manifests are generated by
-- source/viewpoint/export_viewpoint.py.
--
-- Viewpoint 0.1.7+ finds legacy model packs by reading the mods' Lua files: it only
-- recognises a direct register call whose two arguments are string literals. Keep each
-- call below written that way (no pcall wrapper, no table lookup in the arguments), or
-- Viewpoint's addon manager no longer lists the pack.

local registered = {}

local function extendedActive()
    return LiveWire and LiveWire.Compat and LiveWire.Compat.isModActive("batman_LiveWireExtended") or false
end

local function register()
    if not Viewpoint or not Viewpoint.ModelPacks then return end
    if not registered.base then
        registered.base = Viewpoint.ModelPacks.register("batman_LiveWireViewpoint", "media/livewire-viewpoint/livewire.properties")
            and true or nil
    end
    if not registered.extended and extendedActive() then
        registered.extended = Viewpoint.ModelPacks.register("batman_LiveWireViewpoint", "media/livewire-viewpoint/extended.properties")
            and true or nil
    end
end

Events.OnGameBoot.Add(register)
Events.OnGameStart.Add(register)
register()
